std::optional<Halfedge_Mesh::VertexRef> Halfedge_Mesh::bisect_edge(EdgeRef e) {
	//Phase 0: collect existing elements.
	//
	// Sketch of the edge to bisect:
	//
	//        h (on face f)          t (on face g)
	//   v0 ---------->-------- v1   v1 ---------->-------- v0
	//
	HalfedgeRef h = e->halfedge;   //h: v0 -> v1
	HalfedgeRef t = h->twin;       //t: v1 -> v0
	VertexRef v0 = h->vertex;
	VertexRef v1 = t->vertex;
	FaceRef f = h->face;
	FaceRef g = t->face;
	HalfedgeRef h_next = h->next;  //starts at v1 (on f)
	HalfedgeRef t_next = t->next;  //starts at v0 (on g)
	//halfedge before t on g (ends at v1):
	HalfedgeRef t_prev = t_next;
	while (t_prev->next != t) t_prev = t_prev->next;

	//Phase 1: allocate new elements.
	VertexRef vm = emplace_vertex();
	HalfedgeRef h2 = emplace_halfedge(); //will become [vm -> v1] on f
	HalfedgeRef t2 = emplace_halfedge(); //will become [v1 -> vm] on g
	EdgeRef e2 = emplace_edge(e->sharp); //the second half of the split edge

	//Phase 2: set data on new elements.
	vm->position = e->center();
	interpolate_data({v0, v1}, vm); //bone weights, etc.
	interpolate_data({h, h_next}, h2); //corner of h2 is at vm on f
	interpolate_data({t}, t2); //corner of t2 stays at v1 on g
	interpolate_data({t, t_next}, t); //corner of t moves from v1 to vm on g

	//Phase 3: rewire connectivity.
	//
	// After bisection:
	//   f: ... h:[v0 -> vm]  h2:[vm -> v1]  h_next ...
	//   g: ... t_prev  t2:[v1 -> vm]  t:[vm -> v0]  t_next ...
	//
	// e keeps h,t; e2 gets h2,t2.

	//f side:
	h->next = h2;
	h2->set_tnvef(t2, h_next, vm, e2, f);

	//g side:
	t_prev->next = t2;
	t2->set_tnvef(h2, t, v1, e2, g);
	t->vertex = vm;

	//edges:
	e2->halfedge = h2;
	//(e->halfedge stays h)

	//vertices:
	vm->halfedge = t; //lies along e
	if (v1->halfedge == t) v1->halfedge = t2; //t no longer starts at v1
	//(v0, f, g keep their existing pointers, which are still valid)

	return vm;
}

