std::optional<Halfedge_Mesh::VertexRef> Halfedge_Mesh::split_edge(EdgeRef e) {
	// A2L2 (REQUIRED): split_edge

	//Phase 0: collect the adjacent faces before bisecting:
	HalfedgeRef h = e->halfedge;
	HalfedgeRef t = h->twin;
	bool split_f = !h->face->boundary;
	bool split_g = !t->face->boundary;

	//Phase 1: bisect the edge, creating vm and splitting e in two:
	std::optional<VertexRef> vm_ = bisect_edge(e);
	if (!vm_) return std::nullopt; //(should not happen)
	VertexRef vm = *vm_;

	//After bisection:
	// h: [v0 -> vm], h->next: [vm -> v1] (on h's face)
	// t: [vm -> v0] (on t's face)

	//Phase 2: for each adjacent non-boundary face, connect vm to the vertex
	// ccw from the ccw-most end of e within the face, cutting off a triangle.
	// x is a halfedge leaving vm along the (former) split edge:
	auto cut_tip = [&](HalfedgeRef x) {
		FaceRef f = x->face;
		HalfedgeRef xn = x->next;        // [v_end -> w]
		HalfedgeRef xnn = xn->next;      // [w -> ...]
		VertexRef w = xnn->vertex;

		FaceRef nf = emplace_face(false); //the triangle [vm, v_end, w]
		EdgeRef ed = emplace_edge(false); //the new diagonal edge [vm -- w]
		HalfedgeRef d1 = emplace_halfedge(); //[vm -> w] on f
		HalfedgeRef d2 = emplace_halfedge(); //[w -> vm] on nf

		interpolate_data({x, xn}, d1);   //corner at vm
		interpolate_data({xn, xnn}, d2); //corner at w

		//halfedge before x in f (ends at vm):
		HalfedgeRef xp = xnn;
		while (xp->next != x) xp = xp->next;

		//nf loop: d2:[w -> vm], x:[vm -> v_end], xn:[v_end -> w]
		d2->set_tnvef(d1, x, w, ed, nf);
		x->face = nf;
		xn->face = nf;
		xn->next = d2;
		nf->halfedge = d2;

		//f loop: ... xp, d1:[vm -> w], xnn, ...
		xp->next = d1;
		d1->set_tnvef(d2, xnn, vm, ed, f);
		f->halfedge = d1;

		ed->halfedge = d1;
	};

	if (split_f) cut_tip(h->next); //h->next: [vm -> v1] on h's face
	if (split_g) cut_tip(t);       //t: [vm -> v0] on t's face

	return vm;
}

