std::optional<Halfedge_Mesh::EdgeRef> Halfedge_Mesh::flip_edge(EdgeRef e) {
	//A2L1: Flip Edge - works for general polygon faces

	//Phase 0: collect elements.
	//
	//  f: ... pa -> h:[a -> b] -> bn:[b -> c] -> rest ...
	//  g: ... pb -> t:[b -> a] -> an:[a -> d] -> rest ...
	//
	HalfedgeRef h = e->halfedge;
	HalfedgeRef t = h->twin;
	if (h->face->boundary || t->face->boundary) return std::nullopt;

	FaceRef f = h->face;
	FaceRef g = t->face;
	VertexRef a = h->vertex;
	VertexRef b = t->vertex;

	HalfedgeRef bn = h->next;         //[b -> c] on f
	HalfedgeRef rest_f = bn->next;    //starts at c, on f
	VertexRef c = rest_f->vertex;

	HalfedgeRef an = t->next;         //[a -> d] on g
	HalfedgeRef rest_g = an->next;    //starts at d, on g
	VertexRef d = rest_g->vertex;

	//halfedges before h and t:
	HalfedgeRef pa = rest_f;
	while (pa->next != h) pa = pa->next;
	HalfedgeRef pb = rest_g;
	while (pb->next != t) pb = pb->next;

	//Phase 1: validity checks -- would the flipped edge create an invalid mesh?

	//flipped edge would be a self-loop:
	if (c == d) return std::nullopt;
	//d would appear twice in f (or c twice in g):
	{
		HalfedgeRef x = f->halfedge;
		do {
			if (x->vertex == d) return std::nullopt;
			x = x->next;
		} while (x != f->halfedge);
		x = g->halfedge;
		do {
			if (x->vertex == c) return std::nullopt;
			x = x->next;
		} while (x != g->halfedge);
	}
	//an edge between c and d already exists:
	{
		HalfedgeRef x = c->halfedge;
		do {
			if (x->twin->vertex == d) return std::nullopt;
			x = x->twin->next;
		} while (x != c->halfedge);
	}

	//Phase 2: rewire connectivity, rotating e counter-clockwise.
	//
	//  f: ... pa -> an:[a -> d] -> t:[d -> c] -> rest_f ...
	//  g: ... pb -> bn:[b -> c] -> h:[c -> d] -> rest_g ...
	//
	h->vertex = c;
	h->next = pb;
	h->face = g;

	t->vertex = d;
	t->next = rest_f;
	t->face = f;

	pa->next = an;
	an->next = t;
	an->face = f;

	pb->next = bn;
	bn->next = h;
	bn->face = g;

	//fix up vertex / face pointers that referenced moved halfedges:
	if (a->halfedge == h) a->halfedge = an;
	if (b->halfedge == t) b->halfedge = bn;
	f->halfedge = t;
	g->halfedge = h;

