std::optional<Halfedge_Mesh::FaceRef> Halfedge_Mesh::extrude_face(FaceRef f) {
	//A2L4: Extrude Face
	// Reminder: This function does not update the vertex positions.
	// Remember to also fill in extrude_helper (A2L4h)

	if (f->boundary) return std::nullopt;

	//Phase 0: collect the face's halfedges: h[i]: v[i] -> v[i+1]
	uint32_t n = f->degree();
	std::vector<HalfedgeRef> hs;
	std::vector<VertexRef> vs;
	{
		HalfedgeRef h = f->halfedge;
		do {
			hs.push_back(h);
			vs.push_back(h->vertex);
			h = h->next;
		} while (h != f->halfedge);
	}

	//Phase 1: allocate new elements.
	// w[i]:    new vertex inset from v[i]
	// x[i]:    new halfedge [w[i] -> w[i+1]] on f (f becomes the inner face)
	// y[i]:    twin of x[i], [w[i+1] -> w[i]] on side face q[i]
	// sa[i]:   spoke halfedge [v[i+1] -> w[i+1]] on side face q[i]
	// sb[i]:   spoke halfedge [w[i] -> v[i]] on side face q[i]
	// q[i]:    new side quad [v[i], v[i+1], w[i+1], w[i]]
	std::vector<VertexRef> ws(n);
	std::vector<HalfedgeRef> xs(n), ys(n), sa(n), sb(n);
	std::vector<EdgeRef> xe(n), se(n);
	std::vector<FaceRef> qs(n);
	for (uint32_t i = 0; i < n; ++i) {
		ws[i] = emplace_vertex();
		xs[i] = emplace_halfedge();
		ys[i] = emplace_halfedge();
		sa[i] = emplace_halfedge();
		sb[i] = emplace_halfedge();
		xe[i] = emplace_edge(false);
		se[i] = emplace_edge(false);
		qs[i] = emplace_face(false);
	}

	//Phase 2: set data on the new elements.
	for (uint32_t i = 0; i < n; ++i) {
		uint32_t j = (i + 1) % n;
		ws[i]->position = vs[i]->position; //positions are updated by extrude_positions()
		interpolate_data({vs[i]}, ws[i]);        //bone weights, etc.
		interpolate_data({hs[i]}, xs[i]);        //corner at w[i] on inner face
		interpolate_data({hs[j]}, ys[i]);        //corner at w[j] on side face
		interpolate_data({hs[j]}, sa[i]);        //corner at v[j] on side face
		interpolate_data({hs[i]}, sb[i]);        //corner at w[i] on side face
	}

	//Phase 3: rewire connectivity.
	f->halfedge = xs[0];
	for (uint32_t i = 0; i < n; ++i) {
		uint32_t j = (i + 1) % n;
		uint32_t p = (i + n - 1) % n;

		//inner face loop:
		xs[i]->set_tnvef(ys[i], xs[j], ws[i], xe[i], f);
		xe[i]->halfedge = xs[i];
		ws[i]->halfedge = xs[i];

		//side quad loop: hs[i]:[v[i]->v[j]], sa[i]:[v[j]->w[j]], ys[i]:[w[j]->w[i]], sb[i]:[w[i]->v[i]]
		hs[i]->next = sa[i];
		hs[i]->face = qs[i];
		sa[i]->set_tnvef(sb[j], ys[i], vs[j], se[j], qs[i]);
		ys[i]->set_tnvef(xs[i], sb[i], ws[j], xe[i], qs[i]);
		sb[i]->set_tnvef(sa[p], hs[i], ws[i], se[i], qs[i]);
		se[i]->halfedge = sb[i];
		qs[i]->halfedge = hs[i];

		//(v[i]->halfedge still starts at v[i] -- original halfedges kept their vertices)
	}

	return f;
}

