#include "test.h"
#include "geometry/halfedge.h"
#include <iostream>

Test test_a2_zzdebug("a2.zzdebug", []() {
	Halfedge_Mesh mesh = Halfedge_Mesh::from_indexed_faces({
		Vec3{-0.5f, 0.0f,-0.5f}, Vec3{-0.5f, 0.0f, 0.5f},
		Vec3{ 0.5f, 0.0f,-0.5f}, Vec3{ 0.5f, 0.0f, 0.5f}
	},{
		{1, 3, 2, 0}
	});
	std::cout << "before: V=" << mesh.vertices.size() << " E=" << mesh.edges.size() << " F=" << mesh.faces.size() << " B=" << mesh.n_boundaries() << std::endl;
	mesh.linear_subdivide();
	std::cout << "after: V=" << mesh.vertices.size() << " E=" << mesh.edges.size() << " F=" << mesh.faces.size() << " B=" << mesh.n_boundaries() << std::endl;
	if (auto msg = mesh.validate()) {
		std::cout << "INVALID: " << msg.value().second << std::endl;
	}
	for (auto f = mesh.faces.begin(); f != mesh.faces.end(); ++f) {
		std::cout << "face boundary=" << f->boundary << " degree=" << f->degree() << std::endl;
	}
});
EOF
